import{_ as a,o as e,c as t,a2 as n}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Agent State","description":"","frontmatter":{},"headers":[],"relativePath":"guide/state.md","filePath":"guide/state.md","lastUpdated":1793050308000}'),o={name:"guide/state.md"};function l(p,s,c,r,d,i){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="agent-state" tabindex="-1">Agent State <a class="header-anchor" href="#agent-state" aria-label="Permalink to &quot;Agent State&quot;">​</a></h1><p>Each agent has state that outlives its runs: a key-value store and typed document collections. State is scoped to the agent name and lives in the store.</p><h2 id="declaring-collections" tabindex="-1">Declaring collections <a class="header-anchor" href="#declaring-collections" aria-label="Permalink to &quot;Declaring collections&quot;">​</a></h2><p>Declare collections with any <a href="https://standardschema.dev" target="_blank" rel="noreferrer">Standard Schema</a>, such as a zod schema:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> loop = z.object({</span></span>
<span class="line"><span style="color:#E6DFDE;">    title: z.string(),</span></span>
<span class="line"><span style="color:#E6DFDE;">    status: z.enum([</span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">&#39;resolved&#39;</span><span style="color:#E6DFDE;">]),</span></span>
<span class="line"><span style="color:#E6DFDE;">    due: z.string().optional(),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> digest = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Track open loops across days.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    state: { loops: loop },</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: ({ state }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({</span></span>
<span class="line"><span style="color:#E6DFDE;">        countOpenLoops: tool({</span></span>
<span class="line"><span style="color:#E6DFDE;">            description: </span><span style="color:#E7C58C;">&#39;Counts the open loops.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#E6DFDE;">            execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">                const</span><span style="color:#E6DFDE;"> open = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E6DFDE;">).list({ where: { status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E6DFDE;"> } });</span></span>
<span class="line"><span style="color:#FF7B84;">                return</span><span style="color:#E6DFDE;"> open.length;</span></span>
<span class="line"><span style="color:#E6DFDE;">            },</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>A <code>tools</code> factory receives <code>state</code>, typed by the declared schema. A tool built with <code>defineTool()</code> reads it as <code>context.state</code> (<code>defineTool&lt;Input, Output, typeof schema&gt;</code> types it).</p><h2 id="the-state-api" tabindex="-1">The state API <a class="header-anchor" href="#the-state-api" aria-label="Permalink to &quot;The state API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>state.get&lt;T&gt;(key)</code></td><td>Reads a value, <code>undefined</code> when absent</td></tr><tr><td><code>state.set(key, value)</code></td><td>Writes a value</td></tr><tr><td><code>state.collection(name).list({ where?, limit? })</code></td><td>Lists documents as <code>{ id, ...doc }</code>; <code>where</code> matches top-level fields by equality</td></tr><tr><td><code>state.collection(name).upsert(id, doc)</code></td><td>Validates <code>doc</code> with the collection&#39;s schema, then creates or replaces it</td></tr><tr><td><code>state.collection(name).remove(id)</code></td><td>Deletes a document</td></tr></tbody></table><p><code>upsert</code> stores the schema&#39;s output. A document that fails validation throws <code>ValidationError</code> and nothing is stored; its <code>issues</code> hold the validation issues with their paths. Only declared collections are writable.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">try</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E6DFDE;">).upsert(</span><span style="color:#E7C58C;">&#39;x&#39;</span><span style="color:#E6DFDE;">, { title: </span><span style="color:#E7C58C;">&#39;Call Bob&#39;</span><span style="color:#E6DFDE;">, status: </span><span style="color:#E7C58C;">&#39;later&#39;</span><span style="color:#FF7B84;"> as</span><span style="color:#E7C58C;"> &#39;open&#39;</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#E6DFDE;">} </span><span style="color:#FF7B84;">catch</span><span style="color:#E6DFDE;"> (error) {</span></span>
<span class="line"><span style="color:#FF7B84;">    if</span><span style="color:#E6DFDE;"> (error </span><span style="color:#FF7B84;">instanceof</span><span style="color:#E6DFDE;"> ValidationError) {</span></span>
<span class="line"><span style="color:#FF7B84;">        for</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> issue </span><span style="color:#FF7B84;">of</span><span style="color:#E6DFDE;"> error.issues) console.log(issue.path, issue.message);</span></span>
<span class="line"><span style="color:#E6DFDE;">    }</span></span>
<span class="line"><span style="color:#E6DFDE;">}</span></span></code></pre></div><p><code>createAgentState(agent, schema, store)</code> builds the same API outside a run, for scripts, admin tasks and tests:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> store = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> MemoryStore();</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> state = createAgentState(</span><span style="color:#E7C58C;">&#39;digest&#39;</span><span style="color:#E6DFDE;">, { loops: loop }, store);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> state.set(</span><span style="color:#E7C58C;">&#39;lastUid&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#E7C58C;">1042</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> state.get&lt;number&gt;(</span><span style="color:#E7C58C;">&#39;lastUid&#39;</span><span style="color:#E6DFDE;">); </span><span style="color:#958A8B;">// 1042</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> loops = state.collection(</span><span style="color:#E7C58C;">&#39;loops&#39;</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> loops.upsert(</span><span style="color:#E7C58C;">&#39;reply-anna&#39;</span><span style="color:#E6DFDE;">, { title: </span><span style="color:#E7C58C;">&#39;Reply to Anna&#39;</span><span style="color:#E6DFDE;">, status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> loops.list({ where: { status: </span><span style="color:#E7C58C;">&#39;open&#39;</span><span style="color:#E6DFDE;"> }, limit: </span><span style="color:#E7C58C;">10</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#958A8B;">// [{ id: &#39;reply-anna&#39;, title: &#39;Reply to Anna&#39;, status: &#39;open&#39; }]</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> loops.remove(</span><span style="color:#E7C58C;">&#39;reply-anna&#39;</span><span style="color:#E6DFDE;">);</span></span></code></pre></div><h2 id="generated-tools" tabindex="-1">Generated tools <a class="header-anchor" href="#generated-tools" aria-label="Permalink to &quot;Generated tools&quot;">​</a></h2><p>With a <code>state</code> schema, the model gets three tools per collection:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Kind</th><th>Input</th></tr></thead><tbody><tr><td><code>state_&lt;collection&gt;_list</code></td><td>plain tool</td><td><code>{ where?, limit? }</code></td></tr><tr><td><code>state_&lt;collection&gt;_upsert</code></td><td>effect tool</td><td><code>{ id, doc }</code> (the doc&#39;s JSON Schema, when the schema can produce one)</td></tr><tr><td><code>state_&lt;collection&gt;_remove</code></td><td>effect tool</td><td><code>{ id }</code></td></tr></tbody></table><p>An invalid document becomes a tool error the model can correct. Each write gets its own effect key, so a replayed <code>upsert A, upsert B, upsert A</code> sequence still ends on the last write. Your own tools win on a name clash. <code>createStateTools(schema)</code> builds these tools directly; they read the state from their <code>context.state</code>, so call them with a <code>ToolContext</code> (see <a href="/guide/effect-tools#outside-the-engine"><code>wrapToolsForRun</code></a>).</p>`,17)])])}const D=a(o,[["render",l]]);export{y as __pageData,D as default};
